function ensureAudio(){if(!soundOn)return;audio??=new (window.AudioContext||window.webkitAudioContext)();master??=(()=>{const g=audio.createGain();g.gain.value=.2;g.connect(audio.destination);return g})();if(audio.state==='suspended')audio.resume()}
function tone(f,d=.12,kind='triangle',volume=.2,end=f){if(!soundOn||!audio||audio.state!=='running')return;const o=audio.createOscillator(),g=audio.createGain();o.type=kind;o.frequency.setValueAtTime(f,audio.currentTime);o.frequency.exponentialRampToValueAtTime(Math.max(20,end),audio.currentTime+d);g.gain.setValueAtTime(volume,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+d);o.connect(g);g.connect(master);o.start();o.stop(audio.currentTime+d);o.onended=()=>{o.disconnect();g.disconnect()}}
