function music(){if(!soundOn||!audio||mode!=='playing'||time<nextMusic)return;nextMusic=time+(world.level.night?.27:.46);const melody=world.level.night?[220,329.63,440,293.66,261.63,392,329.63,493.88]:[261.63,329.63,392,523.25,440,392,329.63,293.66];tone(melody[musicStep++%8],.35,'triangle',.07);if(musicStep%4===0)tone(world.level.night?110:130.8,.65,'sine',.12)}
